class Solution {
public:
    int collectTheCoins(vector<int>& coins, vector<vector<int>>& edges) {
        int n = coins.size();
        if (n <= 1) return 0;

        vector<unordered_set<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].insert(e[1]);
            adj[e[1]].insert(e[0]);
        }

        // Step 1: Iteratively remove leaves that have no coin
        queue<int> q;
        for (int i = 0; i < n; i++) {
            if (adj[i].size() == 1 && coins[i] == 0) {
                q.push(i);
            }
        }

        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (adj[u].empty()) continue;
            int parent = *adj[u].begin();
            adj[u].clear();
            adj[parent].erase(u);
            if (adj[parent].size() == 1 && coins[parent] == 0) {
                q.push(parent);
            }
        }

        // Step 2: Remove 2 layers of leaves (we can collect at distance 2)
        for (int layer = 0; layer < 2; layer++) {
            vector<int> leaves;
            for (int i = 0; i < n; i++) {
                if (adj[i].size() == 1) {
                    leaves.push_back(i);
                }
            }
            for (int u : leaves) {
                if (adj[u].empty()) continue;
                int parent = *adj[u].begin();
                adj[u].clear();
                adj[parent].erase(u);
            }
        }

        // Count remaining nodes with degree > 0
        int remaining = 0;
        for (int i = 0; i < n; i++) {
            if (adj[i].size() > 0) remaining++;
        }

        return max(0, (remaining - 1) * 2);
    }
};
